-- ---------- Attendance (Aug 1-29, weekdays only, realistic mix) ----------
-- Generate attendance for all assigned labourers across their projects.
-- Using a DO block to generate 1 month of data procedurally.
DO $$
DECLARE
  d date;
  dow int;
  proj_id uuid;
  lab_id uuid;
  roll float;
  att_status public.attendance_status;
BEGIN
  FOR d IN SELECT generate_series('2026-08-01'::date, '2026-08-29'::date, '1 day'::interval)::date LOOP
    dow := extract(dow from d)::int;  -- 0=Sun, 6=Sat
    IF dow = 0 THEN CONTINUE; END IF;  -- Skip Sundays

    FOR proj_id, lab_id IN
      SELECT pl.project_id, pl.labourer_id
      FROM public.project_labourers pl
      WHERE pl.unassigned_at IS NULL
        AND pl.project_id != 'p0000001-0000-0000-0000-000000000009'  -- skip planned project
        AND pl.project_id != 'p0000001-0000-0000-0000-000000000012'  -- skip on-hold project
    LOOP
      roll := random();
      -- Saturdays: 50% show up
      IF dow = 6 AND roll > 0.5 THEN CONTINUE; END IF;

      -- Weekdays: 85% present, 8% half-day, 7% absent
      IF roll < 0.07 THEN
        att_status := 'absent';
      ELSIF roll < 0.15 THEN
        att_status := 'half_day';
      ELSE
        att_status := 'present';
      END IF;

      INSERT INTO public.attendance (labourer_id, project_id, date, status)
      VALUES (lab_id, proj_id, d, att_status)
      ON CONFLICT (labourer_id, date, project_id) DO NOTHING;
    END LOOP;
  END LOOP;
END;
$$;

